-- =====================================================================================
-- 74 · SCA2 · Script de BD para la promoción de la aplicación (2 de 2: CATÁLOGOS)
-- Aurora PostgreSQL / PostgreSQL >= 11 · esquema sca2_anulaciones
-- Datos de los 6 catálogos sca2_cat_* exportados de Appian TEST (listRecordData) el
-- 17/11/2026, incluidas las altas y cambios manuales hechos desde «Gestiones de
-- mantenimiento». Se conservan los ID de TEST.
--
-- Cómo ejecutarlo: después de 73-promocion-bd-sca2-estructura.sql, mismo usuario.
--   psql -v ON_ERROR_STOP=1 -f 74-promocion-bd-sca2-catalogos.sql   |   DBeaver: Alt+X
-- Una sola transacción. Idempotente: las filas cuyo ID ya existe no se tocan
-- (ON CONFLICT DO NOTHING); si un código ya existe con otro ID, el UNIQUE del catálogo
-- hace fallar el script y no se carga nada (revisar ese catálogo en el destino).
-- Las secuencias se ajustan al ID máximo para que las altas desde Appian no choquen.
-- Tras la carga, en Appian: sincronizar los record types SCA2 Cat * si tienen data sync.
-- =====================================================================================
BEGIN;

-- sca2_cat_motivo: 14 filas (ID conservado de TEST)
ON CONFLICT ("ID") DO NOTHING;
DO $$ BEGIN PERFORM setval(pg_get_serial_sequence('sca2_anulaciones.sca2_cat_motivo', 'ID'), GREATEST((SELECT max("ID") FROM sca2_anulaciones.sca2_cat_motivo), 1)); END $$;

-- sca2_cat_detalle: 22 filas (ID conservado de TEST)
ON CONFLICT ("ID") DO NOTHING;
DO $$ BEGIN PERFORM setval(pg_get_serial_sequence('sca2_anulaciones.sca2_cat_detalle', 'ID'), GREATEST((SELECT max("ID") FROM sca2_anulaciones.sca2_cat_detalle), 1)); END $$;

-- sca2_cat_causa: 146 filas (ID conservado de TEST)
ON CONFLICT ("ID") DO NOTHING;
DO $$ BEGIN PERFORM setval(pg_get_serial_sequence('sca2_anulaciones.sca2_cat_causa', 'ID'), GREATEST((SELECT max("ID") FROM sca2_anulaciones.sca2_cat_causa), 1)); END $$;

-- sca2_cat_tipo_argumento: 346 filas (ID conservado de TEST)
ON CONFLICT ("ID") DO NOTHING;
DO $$ BEGIN PERFORM setval(pg_get_serial_sequence('sca2_anulaciones.sca2_cat_tipo_argumento', 'ID'), GREATEST((SELECT max("ID") FROM sca2_anulaciones.sca2_cat_tipo_argumento), 1)); END $$;

-- sca2_cat_concepto: 17 filas (ID conservado de TEST)
ON CONFLICT ("ID") DO NOTHING;
DO $$ BEGIN PERFORM setval(pg_get_serial_sequence('sca2_anulaciones.sca2_cat_concepto', 'ID'), GREATEST((SELECT max("ID") FROM sca2_anulaciones.sca2_cat_concepto), 1)); END $$;

-- sca2_cat_valor_concepto: 101 filas (ID conservado de TEST)
ON CONFLICT ("ID") DO NOTHING;
DO $$ BEGIN PERFORM setval(pg_get_serial_sequence('sca2_anulaciones.sca2_cat_valor_concepto', 'ID'), GREATEST((SELECT max("ID") FROM sca2_anulaciones.sca2_cat_valor_concepto), 1)); END $$;

COMMIT;

-- Verificación (un único JSON): «ok» debe salir true (recuentos iguales a TEST).
SELECT json_build_object(
  'fecha', now(),
  'catalogos', (SELECT json_agg(json_build_object('tabla', e.tabla, 'esperado', e.n, 'real', r.n, 'ok', e.n = r.n))
                  FROM (VALUES
    ('sca2_cat_motivo', 14),
    ('sca2_cat_detalle', 22),
    ('sca2_cat_causa', 146),
    ('sca2_cat_tipo_argumento', 346),
    ('sca2_cat_concepto', 17),
    ('sca2_cat_valor_concepto', 101)
                  ) e(tabla, n)
                  CROSS JOIN LATERAL (SELECT (xpath('/row/c/text()', query_to_xml(
                      format('SELECT count(*) AS c FROM sca2_anulaciones.%I', e.tabla), false, true, '')))[1]::text::int AS n) r),
  'ok', NOT EXISTS (SELECT 1 FROM (VALUES
    ('sca2_cat_motivo', 14),
    ('sca2_cat_detalle', 22),
    ('sca2_cat_causa', 146),
    ('sca2_cat_tipo_argumento', 346),
    ('sca2_cat_concepto', 17),
    ('sca2_cat_valor_concepto', 101)
                  ) e(tabla, n)
                  WHERE (xpath('/row/c/text()', query_to_xml(
                      format('SELECT count(*) AS c FROM sca2_anulaciones.%I', e.tabla), false, true, '')))[1]::text::int <> e.n)
) AS verificacion_catalogos;
